using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    #region CreateOrder – happy path

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 10.00m, 2), ("Gadget", 25.00m, 1));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(45.00m, order.Total);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_ReturnsCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 15.50m, 3));

        // Act
        var order = _service.CreateOrder("cust-2", items);

        // Assert
        Assert.AreEqual(46.50m, order.Total);
        Assert.ContainsSingle(order.Items);
    }

    [TestMethod]
    public void CreateOrder_AssignsUniqueIds()
    {
        // Arrange
        var items = CreateItems(("Widget", 5.00m, 1));

        // Act
        var order1 = _service.CreateOrder("cust-1", items);
        var order2 = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreNotEqual(order1.Id, order2.Id);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentUtcTime()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = CreateItems(("Widget", 5.00m, 1));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after,
            $"CreatedAt {order.CreatedAt} should be between {before} and {after}.");
    }

    #endregion

    #region CreateOrder – validation / exceptions

    [TestMethod]
    public void CreateOrder_NullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems(("Widget", 5.00m, 1));

        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder(null!, items));

        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_NullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _service.CreateOrder("cust-1", null!));

        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_EmptyItems_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_ExistingOrder_ReturnsSameOrder()
    {
        // Arrange
        var items = CreateItems(("Widget", 10.00m, 1));
        var created = _service.CreateOrder("cust-1", items);

        // Act
        var retrieved = _service.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_MultipleOrders_ReturnsAll()
    {
        // Arrange
        var items = CreateItems(("Widget", 5.00m, 1));
        _service.CreateOrder("cust-A", items);
        _service.CreateOrder("cust-A", items);
        _service.CreateOrder("cust-B", items);

        // Act
        var orders = _service.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoOrders_ReturnsEmptyList()
    {
        var orders = _service.GetOrdersByCustomer("unknown");

        Assert.IsEmpty(orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_DoesNotReturnOtherCustomerOrders()
    {
        // Arrange
        var items = CreateItems(("Widget", 5.00m, 1));
        var otherOrder = _service.CreateOrder("cust-B", items);
        _service.CreateOrder("cust-A", items);

        // Act
        var orders = _service.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.DoesNotContain(otherOrder, orders);
    }

    #endregion

    #region CreateOrder – data-driven total calculation

    [TestMethod]
    [DynamicData(nameof(TotalCalculationData))]
    public void CreateOrder_CalculatesCorrectTotal(
        string description, decimal price, int quantity, decimal expectedTotal)
    {
        // Arrange
        var items = CreateItems((description, price, quantity));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.AreEqual(expectedTotal, order.Total);
    }

    public static IEnumerable<(string description, decimal price, int quantity, decimal expectedTotal)>
        TotalCalculationData =>
    [
        ("Single unit", 29.99m, 1, 29.99m),
        ("Multiple units", 10.00m, 5, 50.00m),
        ("Zero price", 0.00m, 10, 0.00m),
        ("Zero quantity", 15.00m, 0, 0.00m),
    ];

    #endregion
}

using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    #region CalculateTotal – happy path

    [TestMethod]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "No tax")]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "10% tax")]
    [DataRow(100.00, 1, 0.25, 125.00, DisplayName = "25% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    #endregion

    #region CalculateTotal – validation

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRange()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, -1, 0.1m));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_NegativeUnitPrice_ThrowsArgumentOutOfRange()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(-5m, 1, 0.1m));

        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Below zero")]
    [DataRow(1.01, DisplayName = "Above one")]
    public void CalculateTotal_InvalidTaxRate_ThrowsArgumentOutOfRange(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, 1, (decimal)taxRate));

        Assert.AreEqual("taxRate", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0.0, DisplayName = "Zero tax")]
    [DataRow(1.0, DisplayName = "100% tax")]
    public void CalculateTotal_BoundaryTaxRate_DoesNotThrow(double taxRate)
    {
        var result = _calculator.CalculateTotal(10m, 1, (decimal)taxRate);

        Assert.IsTrue(result >= 0m);
    }

    #endregion

    #region ApplyDiscount

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)>
        DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 50m, 100m),
        (80m, 0m, 80m),
        (80m, 100m, 0m),
    ];

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Below zero")]
    [DataRow(101.0, DisplayName = "Above 100")]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    #endregion

    #region FormatPrice

    [TestMethod]
    public void FormatPrice_DefaultSymbol_FormatsWithDollarSign()
    {
        var result = _calculator.FormatPrice(19.99m);

        Assert.AreEqual("$19.99", result);
    }

    [TestMethod]
    public void FormatPrice_CustomSymbol_UsesProvidedSymbol()
    {
        var result = _calculator.FormatPrice(19.99m, "€");

        Assert.StartsWith("€", result);
        Assert.AreEqual("€19.99", result);
    }

    [TestMethod]
    public void FormatPrice_RoundsToTwoDecimals()
    {
        var result = _calculator.FormatPrice(9.999m);

        Assert.EndsWith("10.00", result);
    }

    #endregion
}

