using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    #region CalculateTotal – happy path

    [TestMethod]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "No tax")]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "10% tax")]
    [DataRow(100.00, 1, 0.25, 125.00, DisplayName = "25% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    #endregion

    #region CalculateTotal – validation

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRange()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, -1, 0.1m));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_NegativeUnitPrice_ThrowsArgumentOutOfRange()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(-5m, 1, 0.1m));

        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Below zero")]
    [DataRow(1.01, DisplayName = "Above one")]
    public void CalculateTotal_InvalidTaxRate_ThrowsArgumentOutOfRange(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, 1, (decimal)taxRate));

        Assert.AreEqual("taxRate", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0.0, DisplayName = "Zero tax")]
    [DataRow(1.0, DisplayName = "100% tax")]
    public void CalculateTotal_BoundaryTaxRate_DoesNotThrow(double taxRate)
    {
        var result = _calculator.CalculateTotal(10m, 1, (decimal)taxRate);

        Assert.IsTrue(result >= 0m);
    }

    #endregion

    #region ApplyDiscount

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)>
        DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 50m, 100m),
        (80m, 0m, 80m),
        (80m, 100m, 0m),
    ];

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Below zero")]
    [DataRow(101.0, DisplayName = "Above 100")]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRange(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    #endregion

    #region FormatPrice

    [TestMethod]
    public void FormatPrice_DefaultSymbol_FormatsWithDollarSign()
    {
        var result = _calculator.FormatPrice(19.99m);

        Assert.AreEqual("$19.99", result);
    }

    [TestMethod]
    public void FormatPrice_CustomSymbol_UsesProvidedSymbol()
    {
        var result = _calculator.FormatPrice(19.99m, "€");

        Assert.StartsWith("€", result);
        Assert.AreEqual("€19.99", result);
    }

    [TestMethod]
    public void FormatPrice_RoundsToTwoDecimals()
    {
        var result = _calculator.FormatPrice(9.999m);

        Assert.EndsWith("10.00", result);
    }

    #endregion
}

